using Microsoft.AspNetCore.SignalR;

namespace Appizza.Api;

public static class Phase2Endpoints
{
    private const long MaximumMediaBytes = 10 * 1024 * 1024;
    private static readonly HashSet<string> AllowedMediaTypes = new(StringComparer.OrdinalIgnoreCase) { "image/jpeg", "image/png", "image/webp" };

    public static IEndpointRouteBuilder MapPhase2Endpoints(this IEndpointRouteBuilder app)
    {
        var catalog = app.MapGroup("/api/v1/operations/catalog").RequireAuthorization();
        catalog.MapGet("/categories", ListCategories);
        catalog.MapPost("/categories", CreateCategory);
        catalog.MapPut("/categories/{id:guid}", UpdateCategory);
        catalog.MapPost("/categories/{id:guid}/activate", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("category", id, "active", p, d, c));
        catalog.MapPost("/categories/{id:guid}/deactivate", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("category", id, "inactive", p, d, c));
        catalog.MapPost("/categories/{id:guid}/archive", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("category", id, "archived", p, d, c));
        catalog.MapGet("/products", ListProducts);
        catalog.MapPost("/products", CreateProduct);
        catalog.MapPut("/products/{id:guid}", UpdateProduct);
        catalog.MapPost("/products/{id:guid}/activate", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("product", id, "active", p, d, c));
        catalog.MapPost("/products/{id:guid}/deactivate", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("product", id, "inactive", p, d, c));
        catalog.MapPost("/products/{id:guid}/archive", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("product", id, "archived", p, d, c));
        catalog.MapPost("/products/{productId:guid}/variants", CreateVariant);
        catalog.MapGet("/product-variants", ListVariants);
        catalog.MapGet("/ingredients", ListIngredients);
        catalog.MapPost("/ingredients", CreateIngredient);
        catalog.MapPut("/ingredients/{id:guid}", UpdateIngredient);
        catalog.MapPost("/ingredients/{id:guid}/activate", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("ingredient", id, "active", p, d, c));
        catalog.MapPost("/ingredients/{id:guid}/deactivate", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("ingredient", id, "inactive", p, d, c));
        catalog.MapPost("/ingredients/{id:guid}/archive", (Guid id, ClaimsPrincipal p, AppizzaDbContext d, CancellationToken c) => SetLifecycle("ingredient", id, "archived", p, d, c));
        catalog.MapPut("/products/{productId:guid}/ingredients", ConfigureIngredients);
        catalog.MapPut("/products/{productId:guid}/categories", ConfigureProductCategories);
        catalog.MapPut("/products/{productId:guid}/customization-groups", ConfigureProductCustomizationGroups);
        catalog.MapGet("/customization-groups", ListCustomizationGroups);
        catalog.MapPost("/customization-groups", CreateCustomizationGroup);
        catalog.MapGet("/pizza-sizes", ListPizzaSizes);
        catalog.MapPost("/pizza-sizes", CreatePizzaSize);
        catalog.MapGet("/doughs", ListDoughs);
        catalog.MapPost("/doughs", CreateDough);
        catalog.MapGet("/crusts", ListCrusts);
        catalog.MapPost("/crusts", CreateCrust);
        catalog.MapPut("/products/{productId:guid}/pizza-configuration", ConfigurePizza);
        catalog.MapPut("/products/{productId:guid}/combo-configuration", ConfigureCombo);
        catalog.MapPost("/validate", ValidateCatalog);
        catalog.MapPost("/publish", PublishCatalog);
        catalog.MapGet("/publication", CurrentPublication);
        catalog.MapPost("/availability/ingredients/{ingredientId:guid}/change", SetIngredientAvailability);
        catalog.MapPost("/availability/products/{productId:guid}/change", SetProductAvailability);
        catalog.MapPost("/availability/variants/{variantId:guid}/change", SetVariantAvailability);
        catalog.MapGet("/availability", ListAvailability);

        var media = app.MapGroup("/api/v1/operations/media/assets").RequireAuthorization();
        media.MapPost("/", CreateMediaAsset);
        media.MapPut("/{assetId:guid}/content", UploadMediaAsset).DisableAntiforgery();
        media.MapGet("/{assetId:guid}", GetMediaAsset);
        media.MapGet("/{assetId:guid}/content", DownloadMediaAsset);
        media.MapPost("/{assetId:guid}/archive", ArchiveMediaAsset);
        return app;
    }

    private static async Task<IResult> ListCategories(ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.read", ct); if (denied is not null) return denied;
        var tenant = Tenant(principal); return Results.Ok(await db.Set<Category>().Where(x => x.EstablishmentId == tenant).OrderBy(x => x.DisplayOrder).ThenBy(x => x.Name).ToListAsync(ct));
    }

    private static async Task<IResult> CreateCategory(CategoryRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied;
        var tenant = Tenant(principal); if (request.ParentCategoryId is Guid parent && !await db.Set<Category>().AnyAsync(x => x.Id == parent && x.EstablishmentId == tenant, ct)) return Results.NotFound();
        if (!await OwnsReadyMedia(db, tenant, request.ImageMediaId, ct)) return Error(409, "MEDIA_ASSET_NOT_READY", "A mídia não pertence ao estabelecimento ou não está pronta.");
        var now = DateTimeOffset.UtcNow; var entity = new Category { Id = Guid.NewGuid(), EstablishmentId = tenant, ParentCategoryId = request.ParentCategoryId, Name = request.Name.Trim(), Description = request.Description, ImageMediaId = request.ImageMediaId, DisplayOrder = request.DisplayOrder, Status = "active", CreatedAt = now, UpdatedAt = now, CreatedBy = UserId(principal) }; db.Add(entity); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/operations/catalog/categories/{entity.Id}", entity);
    }

    private static async Task<IResult> UpdateCategory(Guid id, CategoryUpdateRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); var entity = await db.Set<Category>().SingleOrDefaultAsync(x => x.Id == id && x.EstablishmentId == tenant, ct); if (entity is null) return Results.NotFound(); if (entity.Status == "archived") return Error(409, "CATALOG_ARCHIVED_IS_TERMINAL", "Entidade arquivada não pode ser editada."); if (entity.Version != request.Version) return Error(409, "CONCURRENCY_CONFLICT", "A entidade foi alterada por outra operação."); if (!await OwnsReadyMedia(db, tenant, request.ImageMediaId, ct)) return Error(409, "MEDIA_ASSET_NOT_READY", "A mídia não pertence ao estabelecimento ou não está pronta."); entity.Name = request.Name.Trim(); entity.Description = request.Description; entity.ParentCategoryId = request.ParentCategoryId; entity.ImageMediaId = request.ImageMediaId; entity.DisplayOrder = request.DisplayOrder; entity.UpdatedAt = DateTimeOffset.UtcNow; entity.UpdatedBy = UserId(principal); await db.SaveChangesAsync(ct); return Results.Ok(entity); }

    private static async Task<IResult> ListProducts(ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.read", ct); if (denied is not null) return denied;
        var tenant = Tenant(principal); return Results.Ok(await db.Set<Product>().Where(x => x.EstablishmentId == tenant).OrderBy(x => x.DisplayOrder).ThenBy(x => x.Name).ToListAsync(ct));
    }

    private static async Task<IResult> CreateProduct(ProductRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied;
        var tenant = Tenant(principal); if (!CatalogRules.ProductTypes.Contains(request.ProductType)) return Error(400, "CATALOG_INVALID_PRODUCT_TYPE", "Tipo de produto inválido.");
        if (request.PrimaryCategoryId is Guid category && !await db.Set<Category>().AnyAsync(x => x.Id == category && x.EstablishmentId == tenant, ct)) return Results.NotFound();
        if (!await OwnsReadyMedia(db, tenant, request.PrimaryImageMediaId, ct)) return Error(409, "MEDIA_ASSET_NOT_READY", "A mídia não pertence ao estabelecimento ou não está pronta.");
        var now = DateTimeOffset.UtcNow; var product = new Product { Id = Guid.NewGuid(), EstablishmentId = tenant, ProductType = request.ProductType, Name = request.Name.Trim(), Description = request.Description, InternalCode = request.InternalCode, PrimaryCategoryId = request.PrimaryCategoryId, PrimaryImageMediaId = request.PrimaryImageMediaId, Status = "active", DisplayOrder = request.DisplayOrder, RequiresProduction = request.RequiresProduction, AllowsNotes = request.AllowsNotes, MaximumNoteLength = request.MaximumNoteLength, PreparationStationId = request.PreparationStationId, CreatedAt = now, UpdatedAt = now, CreatedBy = UserId(principal) }; db.Add(product); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/operations/catalog/products/{product.Id}", product);
    }

    private static async Task<IResult> UpdateProduct(Guid id, ProductUpdateRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); var entity = await db.Set<Product>().SingleOrDefaultAsync(x => x.Id == id && x.EstablishmentId == tenant, ct); if (entity is null) return Results.NotFound(); if (entity.Status == "archived") return Error(409, "CATALOG_ARCHIVED_IS_TERMINAL", "Entidade arquivada não pode ser editada."); if (entity.Version != request.Version) return Error(409, "CONCURRENCY_CONFLICT", "A entidade foi alterada por outra operação."); if (!await OwnsReadyMedia(db, tenant, request.PrimaryImageMediaId, ct)) return Error(409, "MEDIA_ASSET_NOT_READY", "A mídia não pertence ao estabelecimento ou não está pronta."); entity.Name = request.Name.Trim(); entity.Description = request.Description; entity.InternalCode = request.InternalCode; entity.PrimaryCategoryId = request.PrimaryCategoryId; entity.PrimaryImageMediaId = request.PrimaryImageMediaId; entity.DisplayOrder = request.DisplayOrder; entity.RequiresProduction = request.RequiresProduction; entity.AllowsNotes = request.AllowsNotes; entity.MaximumNoteLength = request.MaximumNoteLength; entity.PreparationStationId = request.PreparationStationId; entity.UpdatedAt = DateTimeOffset.UtcNow; entity.UpdatedBy = UserId(principal); await db.SaveChangesAsync(ct); return Results.Ok(entity); }

    private static async Task<IResult> CreateVariant(Guid productId, VariantRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal);
        if (!await db.Set<Product>().AnyAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct)) return Results.NotFound();
        if (!await OwnsReadyMedia(db, tenant, request.ImageMediaId, ct)) return Error(409, "MEDIA_ASSET_NOT_READY", "A mídia não pertence ao estabelecimento ou não está pronta.");
        var now = DateTimeOffset.UtcNow; var variant = new ProductVariant { Id = Guid.NewGuid(), ProductId = productId, Name = request.Name.Trim(), InternalCode = request.InternalCode, BasePrice = request.BasePrice, ImageMediaId = request.ImageMediaId, Status = "active", DisplayOrder = request.DisplayOrder, CreatedAt = now, UpdatedAt = now }; db.Add(variant); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/operations/catalog/products/{productId}/variants/{variant.Id}", variant);
    }

