    private static async Task<IResult> ListCustomizationGroups(ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.read", ct); if (denied is not null) return denied; var tenant = Tenant(principal); return Results.Ok(await db.Set<CustomizationGroup>().Where(x => x.EstablishmentId == tenant).OrderBy(x => x.Name).ToListAsync(ct)); }
    private static async Task<IResult> CreateCustomizationGroup(CustomizationGroupRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; if (request.MinimumSelections < 0 || request.MaximumSelections < request.MinimumSelections) return Error(400, "CATALOG_INVALID_CUSTOMIZATION_LIMITS", "Limites de seleção inválidos."); var tenant = Tenant(principal); var now = DateTimeOffset.UtcNow; var group = new CustomizationGroup { Id = Guid.NewGuid(), EstablishmentId = tenant, Name = request.Name.Trim(), Description = request.Description, SelectionType = request.SelectionType, MinimumSelections = request.MinimumSelections, MaximumSelections = request.MaximumSelections, DisplayType = request.DisplayType, Reusable = request.Reusable, CreatedAt = now, UpdatedAt = now }; db.Add(group); foreach (var option in request.Options ?? []) { if (option.LinkedIngredientId is Guid ingredientId && !await db.Set<Ingredient>().AnyAsync(x => x.Id == ingredientId && x.EstablishmentId == tenant, ct) || option.LinkedProductId is Guid productId && !await db.Set<Product>().AnyAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct)) return Results.NotFound(); db.Add(new CustomizationOption { Id = Guid.NewGuid(), CustomizationGroupId = group.Id, Name = option.Name, Description = option.Description, BaseAdditionalPrice = option.AdditionalPrice, LinkedIngredientId = option.LinkedIngredientId, LinkedProductId = option.LinkedProductId, DisplayOrder = option.DisplayOrder, CreatedAt = now, UpdatedAt = now }); } await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/operations/catalog/customization-groups/{group.Id}", group); }

