    private static async Task<IResult> SetLifecycle(string kind, Guid id, string status, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); CatalogEntity? entity = kind switch { "category" => await db.Set<Category>().SingleOrDefaultAsync(x => x.Id == id && x.EstablishmentId == tenant, ct), "product" => await db.Set<Product>().SingleOrDefaultAsync(x => x.Id == id && x.EstablishmentId == tenant, ct), _ => await db.Set<Ingredient>().SingleOrDefaultAsync(x => x.Id == id && x.EstablishmentId == tenant, ct) }; if (entity is null) return Results.NotFound(); var current = kind switch { "category" => ((Category)entity).Status, "product" => ((Product)entity).Status, _ => ((Ingredient)entity).Status }; if (current == "archived" && status != "archived") return Error(409, "CATALOG_ARCHIVED_IS_TERMINAL", "Entidade arquivada não pode ser reativada."); switch (entity) { case Category category: category.Status = status; break; case Product product: product.Status = status; break; case Ingredient ingredient: ingredient.Status = status; break; } entity.UpdatedAt = DateTimeOffset.UtcNow; await db.SaveChangesAsync(ct); return Results.NoContent();
    }

    private static async Task<IResult> ConfigureIngredients(Guid productId, ProductIngredientsRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal);
        if (!await db.Set<Product>().AnyAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct)) return Results.NotFound();
        var ids = request.Items.Select(x => x.IngredientId).ToArray(); if (await db.Set<Ingredient>().CountAsync(x => ids.Contains(x.Id) && x.EstablishmentId == tenant, ct) != ids.Distinct().Count()) return Results.NotFound();
        var entities = request.Items.Select((item, index) => new ProductIngredient { Id = Guid.NewGuid(), ProductId = productId, IngredientId = item.IngredientId, IncludedByDefault = item.IncludedByDefault, RequiredForRecipe = item.RequiredForRecipe, CanBeRemoved = item.CanBeRemoved, CanBeAdded = item.CanBeAdded, MaximumAdditionalQuantity = item.MaximumAdditionalQuantity, AdditionalPrice = item.AdditionalPrice, DisplayOrder = index, ApplicationScope = item.ApplicationScope, CreatedAt = DateTimeOffset.UtcNow, UpdatedAt = DateTimeOffset.UtcNow }).ToList();
        if (entities.Any(x => !CatalogRules.IsValidIngredientRule(x))) return Error(400, "CATALOG_INVALID_INGREDIENT_RULE", "Ingrediente obrigatório deve estar incluído e não pode ser removível.");
        db.RemoveRange(await db.Set<ProductIngredient>().Where(x => x.ProductId == productId).ToListAsync(ct)); db.AddRange(entities); await db.SaveChangesAsync(ct); return Results.NoContent();
    }

    private static async Task<IResult> ConfigureProductCategories(Guid productId, IdListRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); if (!await db.Set<Product>().AnyAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct)) return Results.NotFound(); var ids = request.Ids.Distinct().ToArray(); if (await db.Set<Category>().CountAsync(x => ids.Contains(x.Id) && x.EstablishmentId == tenant, ct) != ids.Length) return Results.NotFound(); db.RemoveRange(await db.Set<ProductCategory>().Where(x => x.ProductId == productId).ToListAsync(ct)); db.AddRange(ids.Select((id, index) => new ProductCategory { ProductId = productId, CategoryId = id, DisplayOrder = index })); await db.SaveChangesAsync(ct); return Results.NoContent(); }

    private static async Task<IResult> ConfigureProductCustomizationGroups(Guid productId, IdListRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); if (!await db.Set<Product>().AnyAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct)) return Results.NotFound(); var ids = request.Ids.Distinct().ToArray(); if (await db.Set<CustomizationGroup>().CountAsync(x => ids.Contains(x.Id) && x.EstablishmentId == tenant, ct) != ids.Length) return Results.NotFound(); db.RemoveRange(await db.Set<ProductCustomizationGroup>().Where(x => x.ProductId == productId).ToListAsync(ct)); var now = DateTimeOffset.UtcNow; db.AddRange(ids.Select((id, index) => new ProductCustomizationGroup { Id = Guid.NewGuid(), ProductId = productId, CustomizationGroupId = id, DisplayOrder = index, CreatedAt = now, UpdatedAt = now })); await db.SaveChangesAsync(ct); return Results.NoContent(); }

    private static async Task<IResult> ConfigurePizza(Guid productId, PizzaConfigurationRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); var product = await db.Set<Product>().SingleOrDefaultAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct); if (product is null) return Results.NotFound(); if (product.ProductType is not ("pizza" or "custom_pizza")) return Error(409, "CATALOG_PRODUCT_NOT_PIZZA", "Produto não é uma pizza.");
        var sizeIds = request.Sizes.Select(x => x.PizzaSizeId).Distinct().ToArray(); if (await db.Set<PizzaSize>().CountAsync(x => sizeIds.Contains(x.Id) && x.EstablishmentId == tenant, ct) != sizeIds.Length) return Results.NotFound();
        var doughIds = (request.DoughIds ?? []).Distinct().ToArray(); var crustIds = (request.CrustIds ?? []).Distinct().ToArray(); if (await db.Set<Dough>().CountAsync(x => doughIds.Contains(x.Id) && x.EstablishmentId == tenant, ct) != doughIds.Length || await db.Set<Crust>().CountAsync(x => crustIds.Contains(x.Id) && x.EstablishmentId == tenant, ct) != crustIds.Length) return Results.NotFound();
        db.RemoveRange(await db.Set<PizzaProductSize>().Where(x => x.ProductId == productId).ToListAsync(ct)); db.AddRange(request.Sizes.Select(x => new PizzaProductSize { ProductId = productId, PizzaSizeId = x.PizzaSizeId, MaximumFlavorCount = x.MaximumFlavors, DisplayOrder = x.DisplayOrder }));
        if (product.ProductType == "custom_pizza") { db.RemoveRange(await db.Set<CustomPizzaBasePrice>().Where(x => x.CustomPizzaProductId == productId).ToListAsync(ct)); db.AddRange(request.Sizes.Select(x => new CustomPizzaBasePrice { CustomPizzaProductId = productId, PizzaSizeId = x.PizzaSizeId, BasePrice = x.CustomBasePrice ?? 0 })); }
        else { var flavor = await db.Set<PizzaFlavor>().SingleOrDefaultAsync(x => x.ProductId == productId, ct); if (flavor is null) { flavor = new PizzaFlavor { Id = Guid.NewGuid(), ProductId = productId, CreatedAt = DateTimeOffset.UtcNow, UpdatedAt = DateTimeOffset.UtcNow }; db.Add(flavor); } db.RemoveRange(await db.Set<PizzaFlavorPrice>().Where(x => x.PizzaFlavorId == flavor.Id).ToListAsync(ct)); db.AddRange(request.Sizes.Select(x => new PizzaFlavorPrice { Id = Guid.NewGuid(), PizzaFlavorId = flavor.Id, PizzaSizeId = x.PizzaSizeId, Price = x.FlavorPrice ?? 0, CreatedAt = DateTimeOffset.UtcNow, UpdatedAt = DateTimeOffset.UtcNow })); }
        db.RemoveRange(await db.Set<PizzaDough>().Where(x => x.ProductId == productId).ToListAsync(ct)); db.AddRange(doughIds.Select(id => new PizzaDough { ProductId = productId, DoughId = id })); db.RemoveRange(await db.Set<PizzaCrust>().Where(x => x.ProductId == productId).ToListAsync(ct)); db.AddRange(crustIds.Select(id => new PizzaCrust { ProductId = productId, CrustId = id }));
        await db.SaveChangesAsync(ct); return Results.NoContent();
    }

    private static async Task<IResult> ConfigureCombo(Guid productId, ComboConfigurationRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.write", ct); if (denied is not null) return denied; var tenant = Tenant(principal); var product = await db.Set<Product>().SingleOrDefaultAsync(x => x.Id == productId && x.EstablishmentId == tenant, ct); if (product is null) return Results.NotFound(); if (product.ProductType != "combo") return Error(409, "CATALOG_PRODUCT_NOT_COMBO", "Produto não é combo.");
        if (request.Groups.Any(x => x.MinimumSelections < 0 || x.MaximumSelections < x.MinimumSelections || x.Items.Count == 0)) return Error(400, "CATALOG_INVALID_COMBO", "Grupos do combo são inválidos.");
        var combo = await db.Set<Combo>().SingleOrDefaultAsync(x => x.ProductId == productId, ct); if (combo is null) { combo = new Combo { Id = Guid.NewGuid(), ProductId = productId }; db.Add(combo); } combo.PricingStrategy = request.PricingMode; combo.FixedPrice = request.FixedPrice;
        var oldGroups = await db.Set<ComboGroup>().Where(x => x.ComboId == combo.Id).ToListAsync(ct); var oldGroupIds = oldGroups.Select(x => x.Id).ToArray(); db.RemoveRange(await db.Set<ComboGroupItem>().Where(x => oldGroupIds.Contains(x.ComboGroupId)).ToListAsync(ct)); db.RemoveRange(oldGroups); foreach (var group in request.Groups) { var groupEntity = new ComboGroup { Id = Guid.NewGuid(), ComboId = combo.Id, Name = group.Name, MinimumItems = group.MinimumSelections, MaximumItems = group.MaximumSelections, DisplayOrder = group.DisplayOrder, Required = group.MinimumSelections > 0 }; db.Add(groupEntity); foreach (var item in group.Items) { if (!await db.Set<Product>().AnyAsync(x => x.Id == item.ProductId && x.EstablishmentId == tenant, ct) || item.ProductVariantId is Guid variantId && !await (from variant in db.Set<ProductVariant>() join owner in db.Set<Product>() on variant.ProductId equals owner.Id where variant.Id == variantId && owner.EstablishmentId == tenant select variant.Id).AnyAsync(ct)) return Results.NotFound(); db.Add(new ComboGroupItem { Id = Guid.NewGuid(), ComboGroupId = groupEntity.Id, ProductId = item.ProductVariantId is null ? item.ProductId : null, ProductVariantId = item.ProductVariantId, AdditionalPrice = item.AdditionalPrice }); } }
        await db.SaveChangesAsync(ct); return Results.NoContent();
    }

    private static async Task<IResult> ValidateCatalog(ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    { var denied = await Authorize(principal, db, "catalog.read", ct); if (denied is not null) return denied; var errors = await ValidationErrors(db, Tenant(principal), ct); return Results.Ok(new { valid = errors.Count == 0, errors }); }

    private static async Task<IResult> PublishCatalog(HttpRequest request, ClaimsPrincipal principal, AppizzaDbContext db, IHubContext<Phase1Hub> hub, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.publish", ct); if (denied is not null) return denied; if (!request.Headers.TryGetValue("Idempotency-Key", out var key) || string.IsNullOrWhiteSpace(key)) return Error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key é obrigatório.");
        var tenant = Tenant(principal); await using var tx = await db.Database.BeginTransactionAsync(ct); await db.Database.ExecuteSqlInterpolatedAsync($"select pg_advisory_xact_lock(hashtextextended({tenant.ToString()}, 0))", ct);
        var existing = await db.IdempotencyRecords.SingleOrDefaultAsync(x => x.EstablishmentId == tenant && x.OperationType == "catalog.publish" && x.IdempotencyKey == key.ToString(), ct); if (existing is not null) return Results.Content(existing.ResponsePayload ?? "{}", "application/json", Encoding.UTF8, existing.ResponseStatus ?? 200);
        var errors = await ValidationErrors(db, tenant, ct); var snapshot = await BuildSnapshot(db, tenant, ct); var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(snapshot))).ToLowerInvariant(); var now = DateTimeOffset.UtcNow; var state = await db.Set<CatalogState>().SingleOrDefaultAsync(x => x.EstablishmentId == tenant, ct) ?? new CatalogState { EstablishmentId = tenant, CreatedAt = now, UpdatedAt = now };
        if (errors.Count > 0) { var rejected = new CatalogRevision { Id = Guid.NewGuid(), EstablishmentId = tenant, Status = "rejected", Snapshot = snapshot, SemanticHash = hash, ValidationErrors = JsonSerializer.Serialize(errors), CreatedAt = now, PublishedBy = UserId(principal) }; db.Add(rejected); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Error(422, "CATALOG_VALIDATION_FAILED", "O catálogo contém erros."); }
        var current = state.CurrentPublishedRevisionId is Guid currentId ? await db.Set<CatalogRevision>().SingleAsync(x => x.Id == currentId, ct) : null; if (current?.SemanticHash == hash) return Error(409, "CATALOG_NO_CHANGES_TO_PUBLISH", "Não há alterações semânticas para publicar.");
        if (db.Entry(state).State == EntityState.Detached) db.Add(state); if (current is not null) { current.Status = "superseded"; current.SupersededAt = now; }
        var revision = new CatalogRevision { Id = Guid.NewGuid(), EstablishmentId = tenant, CatalogVersion = state.CatalogVersion + 1, Status = "published", Snapshot = snapshot, SemanticHash = hash, CreatedAt = now, PublishedAt = now, PublishedBy = UserId(principal) }; state.CatalogVersion++; state.CurrentPublishedRevisionId = revision.Id; state.UpdatedAt = now; db.Add(revision); AddOutbox(db, tenant, "catalog-published.v1", new { catalogRevisionId = revision.Id, catalogVersion = state.CatalogVersion, semanticHash = hash }, UserId(principal)); var payload = JsonSerializer.Serialize(new { catalogRevisionId = revision.Id, catalogVersion = state.CatalogVersion, semanticHash = hash, publishedAt = now }); db.Add(new IdempotencyRecord { IdempotencyKey = key.ToString(), EstablishmentId = tenant, OperationType = "catalog.publish", RequestHash = hash, ResponseStatus = 200, ResponsePayload = payload, CreatedAt = now }); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); await hub.Clients.Group($"establishment:{tenant}").SendAsync("CatalogPublished", new { catalogVersion = state.CatalogVersion }, ct); return Results.Content(payload, "application/json");
    }

