    private static async Task<IResult> ChangeAvailability(string kind, Guid id, AvailabilityRequest request, HttpRequest http, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "catalog.availability.manage", ct); if (denied is not null) return denied; if (!http.Headers.TryGetValue("Idempotency-Key", out var key) || string.IsNullOrWhiteSpace(key)) return Error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key é obrigatório."); var tenant = Tenant(principal); var exists = kind switch { "ingredient" => await db.Set<Ingredient>().AnyAsync(x => x.Id == id && x.EstablishmentId == tenant, ct), "product" => await db.Set<Product>().AnyAsync(x => x.Id == id && x.EstablishmentId == tenant, ct), _ => await (from variant in db.Set<ProductVariant>() join product in db.Set<Product>() on variant.ProductId equals product.Id where variant.Id == id && product.EstablishmentId == tenant select variant.Id).AnyAsync(ct) }; if (!exists) return Results.NotFound();
        await using var tx = await db.Database.BeginTransactionAsync(ct); await db.Database.ExecuteSqlInterpolatedAsync($"select pg_advisory_xact_lock(hashtextextended({tenant.ToString()}, 1))", ct); var operation = $"catalog.availability.{kind}"; var requestHash = AvailabilityHash(kind, id, request); var previous = await db.IdempotencyRecords.SingleOrDefaultAsync(x => x.EstablishmentId == tenant && x.OperationType == operation && x.IdempotencyKey == key.ToString(), ct); if (previous is not null) return previous.RequestHash == requestHash ? Results.Content(previous.ResponsePayload ?? "{}", "application/json", Encoding.UTF8, previous.ResponseStatus ?? 200) : Error(409, "IDEMPOTENCY_KEY_REUSED", "Idempotency-Key já utilizado com outro conteúdo."); var now = DateTimeOffset.UtcNow; var changed = false;
        if (kind == "ingredient") { var row = await db.Set<IngredientAvailability>().SingleOrDefaultAsync(x => x.IngredientId == id, ct); if (row is null) { row = new IngredientAvailability { IngredientId = id, EstablishmentId = tenant, UpdatedAt = now }; db.Add(row); } changed = row.ExplicitlyAvailable != request.Available; row.ExplicitlyAvailable = request.Available; row.EffectivelyAvailable = request.Available; row.Reason = request.Reason; row.UpdatedAt = now; row.UpdatedBy = UserId(principal); if (changed) { await db.SaveChangesAsync(ct); await RecalculateProducts(db, tenant, now, ct); } }
        else if (kind == "product") { var row = await db.Set<ProductAvailability>().SingleOrDefaultAsync(x => x.ProductId == id, ct); if (row is null) { row = new ProductAvailability { ProductId = id, EstablishmentId = tenant, UpdatedAt = now }; db.Add(row); } changed = row.ExplicitlyAvailable != request.Available; row.ExplicitlyAvailable = request.Available; row.EffectivelyAvailable = request.Available && !await HasUnavailableRequiredIngredient(db, id, ct); row.DerivedReason = row.EffectivelyAvailable ? null : request.Reason ?? "explicit_or_required_ingredient_unavailable"; row.UpdatedAt = now; row.UpdatedBy = UserId(principal); if (changed) await RecalculateVariants(db, tenant, id, row.EffectivelyAvailable, now, ct); }
        else { var row = await db.Set<ProductVariantAvailability>().SingleOrDefaultAsync(x => x.ProductVariantId == id, ct); if (row is null) { row = new ProductVariantAvailability { ProductVariantId = id, EstablishmentId = tenant, UpdatedAt = now }; db.Add(row); } changed = row.ExplicitlyAvailable != request.Available; var productAvailable = await (from variant in db.Set<ProductVariant>() join availability in db.Set<ProductAvailability>() on variant.ProductId equals availability.ProductId into availabilityRows from availability in availabilityRows.DefaultIfEmpty() where variant.Id == id select availability == null || availability.EffectivelyAvailable).SingleAsync(ct); row.ExplicitlyAvailable = request.Available; row.EffectivelyAvailable = request.Available && productAvailable; row.DerivedReason = row.EffectivelyAvailable ? null : request.Reason ?? "explicit_or_product_unavailable"; row.UpdatedAt = now; row.UpdatedBy = UserId(principal); }
        if (!changed) { var noChangePayload = JsonSerializer.Serialize(new { changed = false }); db.Add(new IdempotencyRecord { IdempotencyKey = key.ToString(), EstablishmentId = tenant, OperationType = operation, RequestHash = AvailabilityHash(kind, id, request), ResponseStatus = 200, ResponsePayload = noChangePayload, CreatedAt = now }); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Results.Content(noChangePayload, "application/json"); } var state = await db.Set<CatalogState>().SingleOrDefaultAsync(x => x.EstablishmentId == tenant, ct) ?? new CatalogState { EstablishmentId = tenant, CreatedAt = now, UpdatedAt = now }; if (db.Entry(state).State == EntityState.Detached) db.Add(state); state.AvailabilityVersion++; state.UpdatedAt = now; var effective = kind switch { "ingredient" => db.Set<IngredientAvailability>().Local.Single(x => x.IngredientId == id).EffectivelyAvailable, "product" => db.Set<ProductAvailability>().Local.Single(x => x.ProductId == id).EffectivelyAvailable, _ => db.Set<ProductVariantAvailability>().Local.Single(x => x.ProductVariantId == id).EffectivelyAvailable }; var eventType = kind switch { "ingredient" => "ingredient-availability-changed.v1", "product" => "product-availability-changed.v1", _ => "product-variant-availability-changed.v1" }; AddOutbox(db, tenant, eventType, new { resourceId = id, explicitlyAvailable = request.Available, effectivelyAvailable = effective, reasonCode = request.Reason, availabilityVersion = state.AvailabilityVersion }, UserId(principal)); var payload = JsonSerializer.Serialize(new { changed = true, explicitAvailable = request.Available, effectiveAvailable = effective, availabilityVersion = state.AvailabilityVersion }); db.Add(new IdempotencyRecord { IdempotencyKey = key.ToString(), EstablishmentId = tenant, OperationType = operation, RequestHash = AvailabilityHash(kind, id, request), ResponseStatus = 200, ResponsePayload = payload, CreatedAt = now }); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return Results.Content(payload, "application/json");
    }

    private static async Task<IResult> CreateMediaAsset(MediaAssetRequest request, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "media.write", ct); if (denied is not null) return denied; if (!AllowedMediaTypes.Contains(request.MimeType) || request.FileSize is <= 0 or > MaximumMediaBytes || request.ChecksumSha256.Length != 64 || !request.ChecksumSha256.All(Uri.IsHexDigit)) return Error(400, "MEDIA_INVALID_METADATA", "Metadados de mídia inválidos.");
        var safeName = Path.GetFileName(request.FileName); if (safeName != request.FileName || safeName.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0) return Error(400, "MEDIA_INVALID_FILE_NAME", "Nome de arquivo inválido."); var tenant = Tenant(principal); var now = DateTimeOffset.UtcNow; var asset = new MediaAsset { Id = Guid.NewGuid(), EstablishmentId = tenant, FileName = safeName, ObjectKey = $"{tenant:N}/{Guid.NewGuid():N}/{safeName}", MimeType = request.MimeType.ToLowerInvariant(), FileSize = request.FileSize, ChecksumSha256 = request.ChecksumSha256.ToLowerInvariant(), CreatedAt = now, UpdatedAt = now, CreatedBy = UserId(principal) }; db.Add(asset); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/operations/media/assets/{asset.Id}", new { asset.Id, asset.Status, asset.FileName, asset.MimeType, asset.FileSize });
    }

    private static async Task<IResult> UploadMediaAsset(Guid assetId, HttpRequest request, ClaimsPrincipal principal, AppizzaDbContext db, IObjectStorage storage, CancellationToken ct)
    {
        var denied = await Authorize(principal, db, "media.write", ct); if (denied is not null) return denied; if (!request.Headers.TryGetValue("Idempotency-Key", out var key) || string.IsNullOrWhiteSpace(key)) return Error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key é obrigatório."); var tenant = Tenant(principal); var operation = $"media.upload.{assetId:N}"; var previous = await db.IdempotencyRecords.SingleOrDefaultAsync(x => x.EstablishmentId == tenant && x.OperationType == operation && x.IdempotencyKey == key.ToString(), ct); if (previous is not null) return Results.Content(previous.ResponsePayload ?? "{}", "application/json", Encoding.UTF8, previous.ResponseStatus ?? 200); var asset = await db.Set<MediaAsset>().SingleOrDefaultAsync(x => x.Id == assetId && x.EstablishmentId == tenant, ct); if (asset is null) return Results.NotFound(); if (asset.Status != "pending_upload") return Error(409, "MEDIA_INVALID_STATE", "Asset não aguarda upload."); if (!string.Equals(request.ContentType, asset.MimeType, StringComparison.OrdinalIgnoreCase) || request.ContentLength != asset.FileSize) return Error(400, "MEDIA_CONTENT_MISMATCH", "Conteúdo não corresponde aos metadados.");
        await using var buffer = new MemoryStream(); await request.Body.CopyToAsync(buffer, ct); var checksum = Convert.ToHexString(SHA256.HashData(buffer.ToArray())).ToLowerInvariant(); if (checksum != asset.ChecksumSha256) { asset.Status = "failed"; asset.FailureReason = "checksum_mismatch"; asset.UpdatedAt = DateTimeOffset.UtcNow; await db.SaveChangesAsync(ct); return Error(422, "MEDIA_CHECKSUM_MISMATCH", "Checksum inválido."); } buffer.Position = 0; try { await storage.PutAsync(asset.ObjectKey, buffer, asset.MimeType, ct); } catch { asset.Status = "failed"; asset.FailureReason = "storage_failure"; asset.UpdatedAt = DateTimeOffset.UtcNow; await db.SaveChangesAsync(ct); throw; } asset.Status = "ready"; asset.ReadyAt = DateTimeOffset.UtcNow; asset.UpdatedAt = asset.ReadyAt.Value; var payload = JsonSerializer.Serialize(new { asset.Id, asset.Status }); db.Add(new IdempotencyRecord { IdempotencyKey = key.ToString(), EstablishmentId = tenant, OperationType = operation, RequestHash = checksum, ResponseStatus = 200, ResponsePayload = payload, CreatedAt = DateTimeOffset.UtcNow }); await db.SaveChangesAsync(ct); return Results.Content(payload, "application/json");
    }

    private static async Task<IResult> GetMediaAsset(Guid assetId, ClaimsPrincipal principal, AppizzaDbContext db, CancellationToken ct)
