    private static async Task<List<string>> ValidationErrors(AppizzaDbContext db, Guid tenant, CancellationToken ct)
    {
        var errors = new List<string>(); var products = await db.Set<Product>().Where(x => x.EstablishmentId == tenant && x.Status == "active").ToListAsync(ct);
        foreach (var product in products) { if (product.ProductType == "configurable" && !await db.Set<ProductVariant>().AnyAsync(x => x.ProductId == product.Id && x.Status == "active", ct)) errors.Add($"PRODUCT_VARIANT_REQUIRED:{product.Id}"); if (product.ProductType is "pizza" or "custom_pizza" && !await db.Set<PizzaProductSize>().AnyAsync(x => x.ProductId == product.Id, ct)) errors.Add($"PIZZA_SIZE_REQUIRED:{product.Id}"); if (product.ProductType == "pizza" && !await db.Set<PizzaFlavor>().AnyAsync(x => x.ProductId == product.Id && x.Status == "active", ct)) errors.Add($"PIZZA_FLAVOR_REQUIRED:{product.Id}"); if (product.ProductType == "custom_pizza" && !await db.Set<CustomPizzaBasePrice>().AnyAsync(x => x.CustomPizzaProductId == product.Id, ct)) errors.Add($"CUSTOM_PIZZA_BASE_PRICE_REQUIRED:{product.Id}"); if (product.ProductType == "combo") { var groups = await (from c in db.Set<Combo>() join g in db.Set<ComboGroup>() on c.Id equals g.ComboId where c.ProductId == product.Id select g).ToListAsync(ct); if (groups.Count == 0 || groups.Any(g => g.MaximumItems < g.MinimumItems) || await db.Set<ComboGroupItem>().CountAsync(i => groups.Select(g => g.Id).Contains(i.ComboGroupId), ct) < groups.Count) errors.Add($"COMBO_INVALID:{product.Id}"); } }
        return errors;
    }

    private static async Task<string> BuildSnapshot(AppizzaDbContext db, Guid tenant, CancellationToken ct)
    {
        var categoryRows = await db.Set<Category>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct);
        var productRows = await db.Set<Product>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct); var productIds = productRows.Select(x => x.Id).ToArray();
        var variantRows = await db.Set<ProductVariant>().Where(x => productIds.Contains(x.ProductId) && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct);
        var ingredientRows = await db.Set<Ingredient>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct);
        var productIngredientRows = await db.Set<ProductIngredient>().Where(x => productIds.Contains(x.ProductId)).OrderBy(x => x.Id).ToListAsync(ct);
        var customizationGroups = await db.Set<CustomizationGroup>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct); var customizationGroupIds = customizationGroups.Select(x => x.Id).ToArray(); var customizationOptions = await db.Set<CustomizationOption>().Where(x => customizationGroupIds.Contains(x.CustomizationGroupId) && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct); var productCustomizationGroups = await db.Set<ProductCustomizationGroup>().Where(x => productIds.Contains(x.ProductId) && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct);
        var sizeRows = await db.Set<PizzaSize>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct);
        var pizzaProducts = await db.Set<PizzaProductSize>().Where(x => productIds.Contains(x.ProductId)).OrderBy(x => x.ProductId).ThenBy(x => x.PizzaSizeId).ToListAsync(ct);
        var flavorRows = await db.Set<PizzaFlavor>().Where(x => productIds.Contains(x.ProductId) && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct); var flavorIds = flavorRows.Select(x => x.Id).ToArray();
        var flavorPrices = await db.Set<PizzaFlavorPrice>().Where(x => flavorIds.Contains(x.PizzaFlavorId)).OrderBy(x => x.PizzaFlavorId).ThenBy(x => x.PizzaSizeId).ToListAsync(ct);
        var customBasePrices = await db.Set<CustomPizzaBasePrice>().Where(x => productIds.Contains(x.CustomPizzaProductId)).OrderBy(x => x.CustomPizzaProductId).ThenBy(x => x.PizzaSizeId).ToListAsync(ct);
        var doughs = await db.Set<Dough>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct); var doughIds = doughs.Select(x => x.Id).ToArray(); var doughPrices = await db.Set<DoughSizePrice>().Where(x => doughIds.Contains(x.DoughId)).OrderBy(x => x.DoughId).ThenBy(x => x.PizzaSizeId).ToListAsync(ct); var pizzaDoughs = await db.Set<PizzaDough>().Where(x => productIds.Contains(x.ProductId)).OrderBy(x => x.ProductId).ThenBy(x => x.DoughId).ToListAsync(ct);
        var crusts = await db.Set<Crust>().Where(x => x.EstablishmentId == tenant && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct); var crustIds = crusts.Select(x => x.Id).ToArray(); var crustPrices = await db.Set<CrustSizePrice>().Where(x => crustIds.Contains(x.CrustId)).OrderBy(x => x.CrustId).ThenBy(x => x.PizzaSizeId).ToListAsync(ct); var pizzaCrusts = await db.Set<PizzaCrust>().Where(x => productIds.Contains(x.ProductId)).OrderBy(x => x.ProductId).ThenBy(x => x.CrustId).ToListAsync(ct);
        var comboRows = await db.Set<Combo>().Where(x => productIds.Contains(x.ProductId)).OrderBy(x => x.ProductId).ToListAsync(ct); var comboIds = comboRows.Select(x => x.Id).ToArray();
        var comboGroups = await db.Set<ComboGroup>().Where(x => comboIds.Contains(x.ComboId)).OrderBy(x => x.ComboId).ThenBy(x => x.DisplayOrder).ToListAsync(ct); var groupIds = comboGroups.Select(x => x.Id).ToArray();
        var comboItems = await db.Set<ComboGroupItem>().Where(x => groupIds.Contains(x.ComboGroupId) && x.Status == "active").OrderBy(x => x.Id).ToListAsync(ct);
        return JsonSerializer.Serialize(new
        {
            schemaVersion = 1,
            categories = categoryRows.Select(x => new { x.Id, x.ParentCategoryId, x.Name, x.Description, x.ImageMediaId, x.DisplayOrder }),
            products = productRows.Select(x => new { x.Id, x.ProductType, x.Name, x.ShortName, x.Description, x.InternalCode, x.PrimaryCategoryId, x.PrimaryImageMediaId, x.DisplayOrder, x.RequiresProduction, x.RequiresOperationalAcceptance, x.AllowsNotes, x.MaximumNoteLength, x.PreparationStationId, x.EstimatedPreparationMinutes }),
            variants = variantRows.Select(x => new { x.Id, x.ProductId, x.Name, x.ShortName, x.InternalCode, x.Barcode, x.BasePrice, x.ImageMediaId, x.DisplayOrder }),
            ingredients = ingredientRows.Select(x => new { x.Id, x.Name, x.KitchenName, x.Description, x.DefaultAdditionalPrice, x.UnitOfMeasure, x.ImageMediaId }),
            productIngredients = productIngredientRows.Select(x => new { x.Id, x.ProductId, x.IngredientId, x.IncludedByDefault, x.RequiredForRecipe, x.CanBeRemoved, x.CanBeAdded, x.DefaultQuantity, x.MaximumAdditionalQuantity, x.AdditionalPrice, x.ApplicationScope, x.DisplayOrder }),
            customization = new { groups = customizationGroups.Select(x => new { x.Id, x.Name, x.Description, x.SelectionType, x.MinimumSelections, x.MaximumSelections, x.DisplayType, x.Reusable }), options = customizationOptions.Select(x => new { x.Id, x.CustomizationGroupId, x.Name, x.Description, x.PriceRuleType, x.BaseAdditionalPrice, x.LinkedIngredientId, x.LinkedProductId, x.DisplayOrder }), products = productCustomizationGroups.Select(x => new { x.Id, x.ProductId, x.CustomizationGroupId, x.RequiredOverride, x.MinimumOverride, x.MaximumOverride, x.DisplayOrder }) },
            pizza = new { sizes = sizeRows.Select(x => new { x.Id, x.Name, x.SliceCount, x.DiameterCm, x.DisplayOrder }), products = pizzaProducts, flavors = flavorRows.Select(x => new { x.Id, x.ProductId }), flavorPrices = flavorPrices.Select(x => new { x.Id, x.PizzaFlavorId, x.PizzaSizeId, x.Price }), customBasePrices, doughs = doughs.Select(x => new { x.Id, x.Name, x.Description, x.IsDefault }), doughPrices, pizzaDoughs, crusts = crusts.Select(x => new { x.Id, x.Name, x.Description, x.ImageMediaId }), crustPrices, pizzaCrusts },
            combos = new { definitions = comboRows.Select(x => new { x.Id, x.ProductId, x.PricingStrategy, x.FixedPrice, x.DiscountType, x.DiscountValue }), groups = comboGroups.Select(x => new { x.Id, x.ComboId, x.Name, x.Description, x.MinimumItems, x.MaximumItems, x.AllowRepetition, x.Required, x.DisplayOrder }), items = comboItems.Select(x => new { x.Id, x.ComboGroupId, x.ProductId, x.ProductVariantId, x.CategoryId, x.InclusionType, x.AdditionalPrice, x.FixedQuantity }) }
        });
    }

    private static async Task RecalculateProducts(AppizzaDbContext db, Guid tenant, DateTimeOffset now, CancellationToken ct)
    { var products = await db.Set<Product>().Where(x => x.EstablishmentId == tenant).ToListAsync(ct); foreach (var product in products) { var row = await db.Set<ProductAvailability>().SingleOrDefaultAsync(x => x.ProductId == product.Id, ct); if (row is null) { row = new ProductAvailability { ProductId = product.Id, EstablishmentId = tenant, UpdatedAt = now }; db.Add(row); } var unavailable = await HasUnavailableRequiredIngredient(db, product.Id, ct); row.EffectivelyAvailable = row.ExplicitlyAvailable && !unavailable; row.DerivedReason = unavailable ? "required_ingredient_unavailable" : null; row.UpdatedAt = now; await RecalculateVariants(db, tenant, product.Id, row.EffectivelyAvailable, now, ct); } }
    private static async Task RecalculateVariants(AppizzaDbContext db, Guid tenant, Guid productId, bool productAvailable, DateTimeOffset now, CancellationToken ct)
    { foreach (var variant in await db.Set<ProductVariant>().Where(x => x.ProductId == productId).ToListAsync(ct)) { var row = await db.Set<ProductVariantAvailability>().SingleOrDefaultAsync(x => x.ProductVariantId == variant.Id, ct); if (row is null) { row = new ProductVariantAvailability { ProductVariantId = variant.Id, EstablishmentId = tenant, UpdatedAt = now }; db.Add(row); } row.EffectivelyAvailable = row.ExplicitlyAvailable && productAvailable; row.DerivedReason = row.EffectivelyAvailable ? null : "product_unavailable"; row.UpdatedAt = now; } }
    private static Task<bool> HasUnavailableRequiredIngredient(AppizzaDbContext db, Guid productId, CancellationToken ct) => (from link in db.Set<ProductIngredient>() join availability in db.Set<IngredientAvailability>() on link.IngredientId equals availability.IngredientId where link.ProductId == productId && link.RequiredForRecipe && !availability.EffectivelyAvailable select link.Id).AnyAsync(ct);
    private static async Task<bool> OwnsReadyMedia(AppizzaDbContext db, Guid tenant, Guid? assetId, CancellationToken ct) => assetId is null || await db.Set<MediaAsset>().AnyAsync(x => x.Id == assetId && x.EstablishmentId == tenant && x.Status == "ready", ct);
    private static Guid Tenant(ClaimsPrincipal principal) => Guid.Parse(principal.FindFirstValue("establishment_id")!);
    private static Guid UserId(ClaimsPrincipal principal) => Guid.Parse(principal.FindFirstValue("sub")!);
    private static string AvailabilityHash(string kind, Guid id, AvailabilityRequest request) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{kind}|{id:N}|{request.Available}|{request.Reason}"))).ToLowerInvariant();
    private static async Task<IResult?> Authorize(ClaimsPrincipal principal, AppizzaDbContext db, string permission, CancellationToken ct) { if (!principal.IsTokenType("user")) return Error(403, "INVALID_TOKEN_TYPE", "Token de funcionário necessário."); var permissions = await PermissionResolver.ResolveAsync(db, UserId(principal), DateTimeOffset.UtcNow, ct); return permissions.Contains(permission) ? null : Error(403, "INSUFFICIENT_PERMISSION", "Permissão insuficiente."); }
    private static void AddOutbox(AppizzaDbContext db, Guid tenant, string eventType, object data, Guid userId) => db.Add(new OutboxMessage { Id = Guid.NewGuid(), EstablishmentId = tenant, EventType = eventType, SchemaVersion = 1, Payload = JsonSerializer.Serialize(new { eventId = Guid.NewGuid(), eventType, schemaVersion = 1, occurredAtUtc = DateTimeOffset.UtcNow, establishmentId = tenant, actor = new { userId }, data }), OccurredAt = DateTimeOffset.UtcNow });
    private static IResult Error(int status, string code, string detail) => Results.Problem(statusCode: status, title: detail, detail: detail, extensions: new Dictionary<string, object?> { ["errorCode"] = code });
}

public sealed record CategoryRequest(string Name, string? Description, Guid? ParentCategoryId, Guid? ImageMediaId, int DisplayOrder);
public sealed record CategoryUpdateRequest(string Name, string? Description, Guid? ParentCategoryId, Guid? ImageMediaId, int DisplayOrder, long Version);
public sealed record ProductRequest(string ProductType, string Name, string? Description, string? InternalCode, Guid? PrimaryCategoryId, Guid? PrimaryImageMediaId, int DisplayOrder, bool RequiresProduction, bool AllowsNotes, int? MaximumNoteLength, Guid? PreparationStationId);
public sealed record ProductUpdateRequest(string Name, string? Description, string? InternalCode, Guid? PrimaryCategoryId, Guid? PrimaryImageMediaId, int DisplayOrder, bool RequiresProduction, bool AllowsNotes, int? MaximumNoteLength, Guid? PreparationStationId, long Version);
public sealed record VariantRequest(string Name, string? InternalCode, decimal BasePrice, Guid? ImageMediaId, int DisplayOrder);
public sealed record CustomizationOptionRequest(string Name, string? Description, decimal AdditionalPrice, Guid? LinkedIngredientId, Guid? LinkedProductId, int DisplayOrder);
public sealed record CustomizationGroupRequest(string Name, string? Description, string SelectionType, int MinimumSelections, int? MaximumSelections, string DisplayType, bool Reusable, IReadOnlyList<CustomizationOptionRequest>? Options);
public sealed record PizzaSizeRequest(string Name, string? ShortName, int? SliceCount, decimal? DiameterCm, int DisplayOrder);
public sealed record DoughRequest(string Name, string? Description, bool IsDefault);
public sealed record CrustRequest(string Name, string? Description, Guid? ImageMediaId);
public sealed record IngredientRequest(string Name, string? KitchenName, string? Description, decimal DefaultAdditionalPrice, string? UnitOfMeasure, Guid? ImageMediaId);
public sealed record IngredientUpdateRequest(string Name, string? KitchenName, string? Description, decimal DefaultAdditionalPrice, string? UnitOfMeasure, Guid? ImageMediaId, long Version);
public sealed record ProductIngredientItem(Guid IngredientId, bool IncludedByDefault, bool RequiredForRecipe, bool CanBeRemoved, bool CanBeAdded, decimal? MaximumAdditionalQuantity, decimal AdditionalPrice, string ApplicationScope);
public sealed record ProductIngredientsRequest(IReadOnlyList<ProductIngredientItem> Items);
public sealed record IdListRequest(IReadOnlyList<Guid> Ids);
public sealed record PizzaSizeConfiguration(Guid PizzaSizeId, int MaximumFlavors, int DisplayOrder, decimal? CustomBasePrice, decimal? FlavorPrice);
public sealed record PizzaConfigurationRequest(IReadOnlyList<PizzaSizeConfiguration> Sizes, IReadOnlyList<Guid>? DoughIds, IReadOnlyList<Guid>? CrustIds);
public sealed record ComboItemRequest(Guid ProductId, Guid? ProductVariantId, decimal AdditionalPrice, int DisplayOrder);
public sealed record ComboGroupRequest(string Name, int MinimumSelections, int MaximumSelections, int DisplayOrder, IReadOnlyList<ComboItemRequest> Items);
public sealed record ComboConfigurationRequest(string PricingMode, decimal? FixedPrice, IReadOnlyList<ComboGroupRequest> Groups);
public sealed record AvailabilityRequest(bool Available, string? ReasonCode)
{
    internal string? Reason => ReasonCode;
}
public sealed record MediaAssetRequest(string FileName, string MimeType, long FileSize, string ChecksumSha256);
